e":{"type":"string","enum":["pending","approved","declined","withdrawn"]},"decidedAt":{"type":"string","format":"date-time"},"decidedBy":{"type":"string","pattern":"^did:","maxLength":2048,"description":"The manager who decided. Shown to managers only."}}},"JoinRequestMessage":{"title":"JoinRequestMessage","type":"string","minLength":1,"maxLength":280,"description":"An optional note from the member to the group\'s managers. Plain text."},"GroupId":{"title":"GroupId","description":"Opaque identifier of a community group: `grp_` followed by 16 to 64 base64url characters. Random and community-scoped; not the group\'s DID.","type":"string","pattern":"^grp_[A-Za-z0-9_-]{16,64}\$"},"JoinRequestId":{"title":"JoinRequestId","type":"string","pattern":"^greq_[A-Za-z0-9_-]{16,64}\$"},"EntryId":{"title":"EntryId","description":"Opaque identifier of one directory entry: `dir_` followed by 16 to 64 base64url characters. Random, scoped to one community, and stable for the life of the membership — it survives a rotation of the member\'s DID, which is why groups, notes and cards are keyed by it. It MUST NOT be derived from, and MUST NOT reveal, any DID of the member, and the same person\'s entries in two communities MUST NOT share one. Compared by exact string equality.","type":"string","pattern":"^dir_[A-Za-z0-9_-]{16,64}\$"}}}';

/// The SPEC §7.2 policy for the request variant, taken from this
/// specification's front matter.
///
/// Pass it to [consumeInbound] — items 5b, 7 and 8 are per-specification and
/// cannot be derived from the document alone, and item 2 needs the schema it
/// carries.
const SpecPolicy spec = SpecPolicy(
  typeUri: typeUri,
  isBearer: false,
  isProofRequired: false,
  isRecipientRequired: true,
  isIssuedAtRequired: false,
  payloadSchema: payloadSchemaJson,
);

/// The SPEC §7.2 policy for the success-response variant.
///
/// `isRecipientRequired` tracks the *issuer* party's requirement, because a
/// response swaps the parties (§7.3 item 5).
const SpecPolicy responseSpec = SpecPolicy(
  typeUri: responseTypeUri,
  isBearer: false,
  isProofRequired: false,
  isRecipientRequired: true,
  isIssuedAtRequired: false,
  payloadSchema: responsePayloadSchemaJson,
);
